  (336, '만나기로 한 날 아침에 받으면 웃음이 날 한 줄 쪽지는요?', array['오늘 햇살이 딱 네가 좋아할 색이야.', '커피 대신 코코아 준비해 뒀어.', '가는 길에 웃긴 간판 하나 찾았어.']),
  (339, '숲에 영화관을 짓는다면 맨 뒷자리는 누구 몫일까요?', array['목이 긴 기린이 편히 볼 자리요.', '팝콘을 밤새 까먹을 다람쥐요.', '엔딩에 눈물 많은 곰이요.']),
  (344, '둘이 함께 기르는 상상 속 식물에는 물 대신 뭘 줄까요?', array['하루에 하나씩 작은 칭찬이요.', '둘이 다른 가락으로 콧노래요.', '고맙다고 쓴 꼬마 종이쪽지요.']),
  (349, '오래 기억하고 싶은 데이트의 향을 병에 담는다면 무슨 냄새일까요?', array['비 온 뒤 풀밭에서 나는 흙내요.', '여름 저녁 옥수수 찌는 냄새요.', '햇볕에 말린 무명 셔츠 냄새요.']),
  (359, '잃어버린 물건들이 파티를 연다면 사회는 누가 볼까요?', array['목소리 큰 자전거 경적이요.', '짝 잃은 양말 왼쪽 대표요.', '온 세상을 다닌 지하철 우산이요.']),
  (364, '둘 앞으로 동시에 날아온 신기한 초대장, 무슨 모임이면 좋을까요?', array['구름 위 이불 털기 대회요.', '밤하늘 첫 별 찾는 모임이요.', '무지개 끝에 돗자리 펴는 소풍이요.']),
  (369, '하루만 모든 간판이 그림으로 바뀐다면 빵집은 어떻게 그릴까요?', array['김이 모락모락 나는 갈색 손이요.', '바게트를 베고 잠든 고양이요.', '반죽이 이불처럼 부푸는 모습이요.']),
  (375, '도시 광장의 분수에 물 대신 무엇이 솟으면 한참 볼까요?', array['바람에 흩어지는 비눗방울이요.', '밤에만 피는 색색의 불빛이요.', '하늘로 오르는 종이비행기요.']),
  (379, '직접 만든 행운 부적을 좋아하는 사람에게 준다면 재료는 뭘 쓸까요?', array['해변에서 주운 줄무늬 조약돌이요.', '즐거운 날의 버스표를 접어요.', '짝이 다른 단추 두 개를 묶어요.']),
  (386, '여행에 못 온 상대에게 맛이 나는 풍경 엽서를 만들어 준다면요?', array['눈밭에는 달달한 연유 맛이요.', '파란 바다에는 짭짤한 감자칩이요.', '저녁노을에는 잘 익은 자두 맛이요.']),
  (396, '낡은 트렁크 안에 세상 하나가 있다면 무엇부터 보일까요?', array['기찻길만 한 줄 있는 들판이요.', '성냥갑 크기 빵집의 굴뚝이요.', '자꾸 편지를 뱉는 우체통이요.']),
  (402, '서로에게 색 하나로 취향을 소개한다면 꼭 가져갈 나만의 색은요?', array['늦여름 잎사귀의 짙은 초록이요.', '이른 새벽이 밝아오는 남색이요.', '구운 빵 가장자리의 황금빛이요.']),
  (408, '데이트 약속 장소에 웃기는 표지판 하나를 세운다면 문구는요?', array['이 앞은 고양이 낮잠 보호 구역.', '급한 마음은 벤치에 잠깐 두세요.', '저녁노을 구경으로 지체될 수 있음.']),
  (414, '다음에 다시 만날 상대를 위해 남겨 둘 작은 반전은 뭘까요?', array['빌려줄 책 중간에 쪽지를 끼워요.', '저번에 본 고양이를 그림으로 그려요.', '함께 찍은 사진으로 퍼즐을 만들어요.']),
  (420, '데이트 코스의 두 장소를 요술 다리로 이으면 어디와 어디일까요?', array['뒤뜰에서 햇볕 좋은 벤치까지요.', '강 양쪽의 자전거길 사이요.', '도서관 옥상과 작은 천문대요.']),
  (423, '같이 보내는 날 한 가지 자잘한 수고를 없앨 수 있다면 뭘까요?', array['귤에 붙은 흰 실 떼는 일이요.', '첫 장에 붙은 테이프 끝 찾기요.', '다 씻고 난 뒤 머리카락 줍기요.']),
  (430, '시간 여행으로 내 이야기를 들려준다면 어느 한 시간에 초대할까요?', array['강아지 무서워하던 내가 쓰다듬던 때요.', '처음 무대에서 목소리가 떨리던 날이요.', '어릴 때 가족과 갔던 봄 소풍이요.']),
  (438, '다음 데이트를 동네 행진으로 시작한다면 맨 앞에 누가 설까요?', array['바람개비 단 유모차들이요.', '뜨개옷 입은 자전거 행렬이요.', '빗자루를 든 빵집 직원들이요.']),
  (443, '둘만 아는 감탄사를 만든다면 어떤 순간에 쓰는 말일까요?', array['막 구운 빵을 찢을 때 빵하!', '양말 짝을 찾았을 때 짝콩!', '버스를 딱 탔을 때 슝착!']),
  (447, '하루만 물방울이 된다면 어디로 굴러가고 싶나요?', array['연잎 가운데로 통통 튈래요.', '유리창을 타고 화분으로요.', '수달 콧등에서 강물로요.']),
  (451, '소개팅에서 가벼운 스무고개를 시작한다면 정답은 뭘로 할까요?', array['손잡이 둘 달린 가위요.', '늘 입을 벌리고 선 빨래집게요.', '쉬지 않고 도는 전자레인지 접시요.']),
  (460, '내 기억을 향수로 만들어 서로 바꾼다면 내 향수의 이름은요?', array['마지막 종이 울린 여름방학.', '소풍 가기 전날의 밤잠.', '처음 만든 볶음밥 한 접시.']),
  (466, '꿈에서 본 장소에 문패를 건다면 어떤 이름을 붙일까요?', array['발을 구르면 열리는 구름 다락이요.', '일요일만 모아 둔 골목이요.', '비를 맡아 주는 유리 정거장이요.']),
  (470, '미래에 다녀온 내가 좋아하는 사람에게 건넬 기념품은 뭘까요?', array['백 년 뒤 동네 산책 지도요.', '미래 사람들이 즐겨 쓰는 농담집이요.', '그 시대 운동회의 응원 도구요.']),
  (477, '데이트하다 일이 꼬이면 둘만의 어떤 규칙으로 웃어넘길까요?', array['버스를 놓치면 붕어빵 쉬는 시간이요.', '흘린 물자국으로 얼굴 맞히기요.', '식당이 쉬면 옆집에 별명 붙이기요.']),
  (486, '둘이 라디오에 사연 대신 소리만 보낸다면 어떻게 들려줄까요?', array['돌다리를 번갈아 건너는 발소리요.', '컵에 얼음 넣고 같이 짠 하는 소리요.', '동전 두 개를 돌리다 웃는 소리요.']),
  (492, '종이 한 장을 접어 두 사람 탈것을 만든다면 어떤 모양일까요?', array['부채처럼 접어 바람을 탈래요.', '개구리로 접고 통통 뛰어요.', '종이학 두 날개 사이에 앉아요.']),
  (494, '백 년 된 나무 아래 앉아 둘이 듣고 싶은 이야기는 무엇인가요?', array['맨 꼭대기에 처음 둥지 튼 새요.', '백 년 전에 사람들이 추던 춤이요.', '그늘 아래서 이뤄진 첫 고백이요.']),
  (502, '데이트 끝에 둘만 마지막 손님으로 남으면 어떤 특전이 반가울까요?', array['폐점 음악을 직접 고르는 권리요.', '다음 날 첫 쿠키 이름 짓기요.', '불 끄는 큰 버튼을 누르는 재미요.']),
  (508, '상대와 탐험 게임 중이에요. 반짝이는 돌과 비밀 지도 중 뭘 고를까요?', array['돌이 계속 빛나는지 지켜볼래요.', '지도 뒷면의 쪽지부터 읽어요.', '지도를 골라 돌의 위치를 표시해요.']),
  (513, '노래하는 문 앞에서 만나기로 했다면 어떤 소리가 나는 문일까요?', array['하품 소리를 내는 침실 문이요.', '박수처럼 열리는 극장 문이요.', '경쾌하게 딸랑거리는 빵집 문이요.']),
  (519, '좋아하는 사람과 걷는 길에 발자국 대신 어떤 그림을 남길까요?', array['빗길마다 작은 금붕어 무늬요.', '두 걸음마다 피는 민들레요.', '걸을 때 이어지는 오선지요.']),
  (527, '데이트용 나침반이 북쪽 대신 가리켜 줬으면 하는 곳은 어디예요?', array['제일 편한 등받이 의자요.', '가까이서 막 구운 빵이 있는 쪽이요.', '지금 노을이 잘 보이는 방향이요.']),
  (530, '서랍 하나가 과거의 나와 연결된다면 뭘 넣어 둘까요?', array['발 안 까지는 새 운동화요.', '지금도 좋아하는 만화 속 스티커요.', '틀려도 괜찮다고 적은 지우개요.']),
  (536, '한 시간짜리 재능을 빌려 상대에게 짧은 공연을 해준다면요?', array['피아노로 상대 이름을 연주해요.', '분필로 발밑에 꽃다발을 그려요.', '귤 세 개로 저글링을 해요.']),
  (543, '데이트가 끝날 때 상대에게 받으면 은근히 뿌듯할 훈장은요?', array['낯선 강아지 잘 기다려 준 상이요.', '마지막 한 조각 잘 나눈 상이요.', '포기할 뻔한 날 산책 간 상이요.']),
  (552, '첫 소풍 가는 날, 바구니에 몰래 챙겨 갈 날씨는 어떤 건가요?', array['돗자리가 안 날아갈 산들바람이요.', '눈 안 찡그려도 되는 옅은 구름이요.', '귓불만 살짝 시린 가을 햇살이요.']),
  (557, '이야기하는 벤치를 찾아 데이트한다면 어느 자리로 가고 싶나요?', array['종점에서 기사를 기다리는 벤치요.', '놀이공원 키 재는 벽 앞 벤치요.', '새벽에 빵집 셔터를 보는 벤치요.']),
  (562, '우리의 모험에 길잡이가 될 작은 로봇은 뭘 잘하면 될까요?', array['배고픈 표정을 제일 먼저 알아채요.', '왔던 길의 돌 모양을 기억해요.', '기운 없을 때 엉뚱한 퀴즈를 내요.']),
  (566, '둘이 같은 꿈을 골라 꿀 수 있다면 그 꿈은 어떻게 끝날까요?', array['다시 만날 날짜를 정하고 깨요.', '언덕을 넘자 바다가 보이는 장면이요.', '다 같이 원탁에서 수프를 먹어요.']),
  (575, '좋아하는 사람을 만나러 가는 길, 신발에 어떤 기능을 켤까요?', array['웅덩이를 만나면 살짝 뛰어넘어요.', '길을 잊으면 두 번 톡톡 울려요.', '계단을 오를 때 작은 박수를 쳐요.']),
  (578, '힘든 날 만난 상대에게 나뭇잎 편지를 준다면 어떤 응원을 쓸까요?', array['오늘의 실패담은 내가 들어 줄게.', '오늘은 숙제 없는 날로 정하자.', '최선을 다한 것 내가 옆에서 봤어.']),
  (587, '둘이 만든 작은 왕국에서 서로를 위해 정하고 싶은 첫 규칙은요?', array['낮잠 자는 사람을 놀라게 하지 않기요.', '모든 놀이터에 어른 그네도 두기요.', '마지막 과자는 반으로 나누기요.']),
  (591, '편지가 길을 스스로 찾는다면 받는 사람을 어떻게 적을까요?', array['오늘 혼자 케이크에 초를 꽂은 분.', '빈자리 옆에 가방을 치워 준 사람.', '오랫동안 새싹 하나를 기다린 이.']),
  (595, '떨리는 첫 만남을 앞두고 나에게 걸어 줄 세 글자 주문은요?', array['발 걸 음! 일단 걸어 나가요.', '콩 닥 콩! 재밌는 일이 생겨요.', '뭐 어 때! 실수할 용기를 내요.']),
  (601, '장난감 집이 데이트 장소가 된다면 가장 먼저 같이 해볼 일은요?', array['미끄럼틀 계단을 타고 내려와요.', '숨겨진 벽지를 살짝 들춰 봐요.', '작은 찻잔에 진짜 차를 따라요.']),
  (609, '아무 물체나 한 번 통역해 주는 전화로 어디에 걸까요?', array['늘 잠겨 있는 낡은 일기장이요.', '파도 밑을 아는 조개껍데기요.', '종일 달리는 버스 손잡이요.']),
  (617, '상대가 낸 미션으로 한 블록을 걷는다면 어떤 지시가 재밌을까요?', array['반짝이는 게 보이는 쪽으로 가요.', '새소리가 끊길 때까지 왼쪽으로요.', '동그라미 세 개를 찾으면 멈춰요.']),
  (619, '내일 모든 횡단보도가 건널 때 반응한다면 어떤 게 좋을까요?', array['줄무늬마다 피아노 소리가 나요.', '건너온 발자국만 꽃으로 피어요.', '마지막 칸에서 깃발이 펄럭여요.']),
  (625, '마음을 표현할 용기가 딱 한 번 충전된다면 어디에 쓸 건가요?', array['다음번에도 만나고 싶다고 말해요.', '쓴 편지를 가방에서 꺼내 건네요.', '처음 봤을 때 좋았던 점을 말해요.']),
  (633, '데이트가 끝나면 모형으로 만들어 간직하고 싶은 순간은요?', array['간발의 차로 같이 탄 막차요.', '나란히 앉아 보던 이상한 모양 구름이요.', '처음 맞잡은 손과 커다란 장갑이요.']),
  (638, '데이트가 끝나면 둘만의 우체통에 무엇을 하나 남기고 싶나요?', array['오늘 가장 크게 웃었던 단어 하나요.', '다음에 함께 듣고 싶은 노래 제목이요.', '마주 앉았던 자리를 그린 낙서요.']),
  (643, '약속을 잡을 때 마법 지도에 어떤 장소만 반짝이면 편할까요?', array['오래 앉아도 편한 벤치만이요.', '오늘 문을 연 작은 전시장이요.', '길고양이가 잘 자는 따뜻한 담장이요.']),
  (649, '둘이 의견을 못 정해 동전을 던진다면 앞뒤에 뭘 걸까요?', array['앞은 자전거, 뒤는 걸어서 소풍이요.', '앞은 내가 요리, 뒤는 네가 간 보기요.', '앞은 상상 그림, 뒤는 관찰 그림이요.']),
  (660, '첫 데이트 선물로 감정을 한 숟갈 살 수 있다면 뭘 고를까요?', array['첫 장을 넘길 때의 기대감이요.', '약속 장소에 먼저 온 설렘이요.', '비가 그친 뒤의 안도감이요.']),
  (662, '좋아하는 사람이 돌아가는 길에 작은 등불을 어디에 놓아 줄까요?', array['비바람 부는 버스 정류장 표지판이요.', '헤어지며 돌아보는 골목 모퉁이요.', '열쇠 찾기 힘든 오래된 현관이요.']),
  (672, '다음 데이트 날을 달력의 아무 날과 바꾼다면 언제로 바꿀까요?', array['내일이랑 바꿔서 서프라이즈 할래요.', '첫눈 오는 날이랑 하루 바꿀래요.', '휴일 전날의 들뜸을 먼저 빌려요.']),
  (675, '사라진 색 하나를 되찾으러 간다면 어떤 물건을 단서로 삼을까요?', array['노랑은 레몬 껍질에서 시작해요.', '파랑은 잉크 묻은 손끝이 단서요.', '분홍은 복숭아 꼭지를 따라가요.']),
  (683, '커플이 한 팀인 운동회에서 둘이 같이 웃으며 해볼 종목은요?', array['둘이 이어 그린 미로 빠져나오기요.', '바람 멈출 때까지 깃털 띄우기요.', '가장 느린 종이배 응원하기요.']),
  (689, '서로를 위한 30초짜리 깜짝 공연에서 맡고 싶은 역할은요?', array['손전등으로 그림자 강아지를 만들어요.', '숟가락 두 개로 비 오는 소리를 내요.', '마지막에 종이꽃을 툭 피워요.']),
  (695, '꿈속 우체부가 두 사람 앞으로 보내 줬으면 하는 소포는요?', array['예전 꿈에서 놓친 버스의 승차권이요.', '열면 파도 소리가 나는 작은 서랍이요.', '다시 날 수 있는 종이 날개 한 쌍이요.']),
  (701, '손이 모자란 상대를 돕는다면 문어팔 여덟 개를 언제 꺼낼까요?', array['이불 커버 네 귀퉁이를 맞출 때요.', '소풍 도시락을 한꺼번에 펼칠 때요.', '작은 오케스트라를 혼자 지휘할 때요.']),
  (703, '처음 만난 상대가 긴장을 많이 했다면 어떤 첫마디로 풀어 줄까요?', array['저도 메뉴판만 세 번째 읽고 있어요.', '어색하면 강아지 얘기부터 할까요?', '우리 인사는 천천히 다시 해 봐요.']),
  (712, '둘만의 기념일 아침, 거리에서 어떤 작은 신호가 켜지면 좋을까요?', array['창틀에 작은 은방울이 울려요.', '길모퉁이 돌마다 무늬가 생겨요.', '가로등이 저녁에 한 번씩 깜빡여요.']),
  (718, '데이트 중 과일을 나눠 먹자 음악이 난다면 어떤 조합이 어울릴까요?', array['청사과에서 맑은 트라이앵글 소리요.', '수박에서 묵직한 큰북 소리요.', '복숭아에서 나른한 첼로 소리요.']),
  (724, '같이 걷다가 돋보기를 꺼내 보여 주고 싶은 작은 풍경은요?', array['갓 마른 물감 가장자리의 무늬요.', '낡은 동전 여행의 긁힌 흔적이요.', '비누 거품 속에 뜨는 무지개요.']),
  (730, '다음 첫인사를 위해 엉뚱한 명함 하나를 만든다면 직함은요?', array['길가 고양이 눈인사 담당이요.', '마지막 감자튀김 양보 위원이요.', '산책길 구름 이름 짓는 사람이요.']);
